#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int n;
vector<int> defense;
vector<vector<int>> adj;
vector<int> down_dp, up_dp;
vector<ll> ans;

void dfs_down(int u, int p) {
    down_dp[u] = defense[u];
    for (int v : adj[u]) {
        if (v == p) continue;
        dfs_down(v, u);
        down_dp[u] = max(down_dp[u], down_dp[v]);
    }
}

void dfs_up(int u, int p) {
    // 先累加父侧的 up 值
    ll res = up_dp[u];
    // 统计当前节点的子树 down 值之和与最大／次大
    int mx1 = -1, mx2 = -1;
    for (int v : adj[u]) {
        if (v == p) continue;
        res += down_dp[v];
        if (down_dp[v] > mx1) {
            mx2 = mx1;
            mx1 = down_dp[v];
        } else if (down_dp[v] > mx2) {
            mx2 = down_dp[v];
        }
    }
    ans[u] = res;

    // 计算子节点的 up 值并递归
    int use_up = max(up_dp[u], defense[u]);
    for (int v : adj[u]) {
        if (v == p) continue;
        int best = (down_dp[v] == mx1 ? mx2 : mx1);
        up_dp[v] = max(use_up, best);
        dfs_up(v, u);
    }
}

int main(){
