        cin >> u >> v;
        --u; --v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    down_dp.assign(n, 0);
    up_dp.assign(n, 0);
    ans.assign(n, 0);

    dfs_down(0, -1);
    dfs_up(0, -1);

    // 输出
    for (int i = 0; i < n; i++) {
        cout << ans[i] << (i+1<n ? ' ' : '\n');
    }
    return 0;
}
