import sys
sys.setrecursionlimit(200000)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    w = [int(next(it)) for _ in range(n)]
    adj = [[] for _ in range(n)]
    for _ in range(n - 1):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        adj[u].append(v)
        adj[v].append(u)

    down = [0] * n     # 子树内最大处理能力
    up = [0] * n       # 父侧连通分量的最大处理能力
    ans = [0] * n

    def dfs_down(u, parent):
        down[u] = w[u]
        for v in adj[u]:
            if v == parent:
                continue
            dfs_down(v, u)
            if down[v] > down[u]:
                down[u] = down[v]

    def dfs_up(u, parent):
        # 当前节点宕机后的总剩余处理能力
        total = up[u]
        mx1 = -1   # 所有儿子 down 的最大值
        mx2 = -1   # 所有儿子 down 的次大值
        for v in adj[u]:
            if v == parent:
                continue
            total += down[v]
            if down[v] > mx1:
                mx2 = mx1
                mx1 = down[v]
            elif down[v] > mx2:
                mx2 = down[v]
        ans[u] = total

        # 计算来自父侧的基准最大值
        use = up[u]
        if w[u] > use:
            use = w[u]

        for v in adj[u]:
            if v == parent:
                continue
            best = mx2 if down[v] == mx1 else mx1
            up[v] = use
            if best > up[v]:
                up[v] = best
            dfs_up(v, u)

    dfs_down(0, -1)
    dfs_up(0, -1)

    print(' '.join(str(x) for x in ans))

if __name__ == "__main__":
    solve()
```

