    up.assign(n, 0);
    ans.assign(n, 0);

    dfsDown(0, -1);
    dfsUp(0, -1);

    for (int i = 0; i < n; i++) {
        cout << ans[i] << (i + 1 < n ? ' ' : '\n');
    }
    return 0;
